patches.after:
let filename = 'system.node';
if (platform === 'linux') {
    // DSHA_NO_GETREPORT_LIBC_V1: 不用 process.report.getReport() 判断 libc。
    // 在 proot 容器里 getReport() 要读大量 /proc 与系统文件，穿透开销极大
    // （实测一次调用阻塞事件循环 76 秒，发生在首次会话写入拿 flock 时）。
    // 改为直接看文件系统特征：有 glibc 的 loader/共享库即 glibc，否则视为 musl。
    const reportFreeIsGlibc = () => {
        try {
            const { existsSync } = createRequire(import.meta.url)('node:fs');
            // glibc 的 loader（各架构名不同）或 libc 共享库，命中任一即认定 glibc。
            const markers = [
                '/lib64/ld-linux-x86-64.so.2', '/lib/ld-linux-aarch64.so.1',
                '/lib/ld-linux-armhf.so.3', '/lib/ld-linux.so.3',
                '/usr/lib/aarch64-linux-gnu/libc.so.6', '/lib/aarch64-linux-gnu/libc.so.6',
                '/usr/lib/x86_64-linux-gnu/libc.so.6', '/lib/x86_64-linux-gnu/libc.so.6',
                '/etc/ld.so.cache',
            ];
            for (const marker of markers) if (existsSync(marker)) return true;
            return false;
        } catch {
            // 判断失败时按 glibc 处理：Ubuntu rootfs 是本应用的固定基础环境。
            return true;
        }
    };
    filename = join(reportFreeIsGlibc() ? 'glibc' : 'musl', filename);
}
